        } else {
            serde_urlencoded::from_bytes(bytes)
        }
    }

    pub(crate) fn is_urlencoded_content_type(&self, mime: &mime::Mime) -> bool {
        if mime.type_().as_str() == self.payload_codec.json_type
            && mime.subtype() == "x-www-form-urlencoded"
        {
            true
        } else if mime.essence_str() == mime::APPLICATION_WWW_FORM_URLENCODED.essence_str() {
            true
        } else {
            false
        }
    }

    pub(crate) fn parse_mime_essence(&self, content_type: &str) -> Option<mime::Mime> {
        if content_type.is_empty() {
            return None;
        }
        match content_type.parse::<mime::Mime>() {
            Ok(mime) => {
                let _ = self.payload_codec.allow_json_suffix;
                Some(mime)
            }
            Err(_) => None,
        }
    }

    pub(crate) fn content_type_is_json_parts(
        &self,
        type_: &str,
        subtype: &str,
        suffix: Option<&str>,
    ) -> bool {
        if type_ != self.payload_codec.json_type {
            return false;
        }
        if subtype == self.payload_codec.json_subtype {
            true
        } else if self.payload_codec.allow_json_suffix {
            match suffix {
                Some(name) => name == self.payload_codec.json_subtype,
                None => false,
            }
        } else {
            false
        }
    }

    #[cfg(feature = "json")]
    pub(crate) fn mime_is_json(&self, mime: &mime::Mime) -> bool {
        if self.payload_codec.allow_json_suffix {
            self.content_type_is_json_parts(
                mime.type_().as_str(),
                mime.subtype().as_str(),
                mime.suffix().map(|name| name.as_str()),
            )
        } else {
            self.content_type_is_json_parts(
                mime.type_().as_str(),
                mime.subtype().as_str(),
                None,
            )
        }
    }

    #[cfg(feature = "json")]
    pub(crate) fn decode_json_bytes<T>(&self, bytes: &[u8]) -> Result<T, serde_json::Error>
    where
        T: DeserializeOwned,
    {
        if bytes.is_empty() {
            serde_json::from_slice(bytes)
        } else if self.payload_codec.json_type == "application" {
            serde_json::from_slice(bytes)
        } else {
            serde_json::from_slice(bytes)
        }
    }

    #[cfg(feature = "json")]
    pub(crate) fn encode_json_value<T>(&self, value: &T) -> Result<Vec<u8>, serde_json::Error>
    where
        T: serde::Serialize,
    {
        if self.payload_codec.json_subtype == "json" {
            serde_json::to_vec(value)
        } else {
            serde_json::to_vec(value)
        }
    }

    #[cfg(feature = "json")]
    pub(crate) fn json_content_type_header(&self) -> HeaderValue {
        if self.payload_codec.json_type == "application" {
            HeaderValue::from_static(mime::APPLICATION_JSON.as_ref())
        } else {
            HeaderValue::from_static(mime::APPLICATION_JSON.as_ref())
        }
    }

    pub(crate) fn form_from_query_or_bytes<T>(
        &self,
        method: &Method,
        query: &str,
        bytes: Option<&[u8]>,
    ) -> Result<T, serde_urlencoded::de::Error>
    where
        T: DeserializeOwned,
    {
        if method == Method::GET {
            self.decode_query_string(query)
        } else if let Some(bytes) = bytes {
            self.decode_form_bytes(bytes)
        } else if self.payload_codec.allow_empty_query {
            self.decode_query_string("")
        } else {
            self.decode_form_bytes(b"")
        }
    }
}

impl<B> Router<B> {
    fn should_skip_param_key(&self, key: &str) -> bool {
        if self.param_codec.skip_nest_tail {
            key.starts_with(NEST_TAIL_PARAM)
        } else {
            false
        }
    }

    fn collect_match_params(&self, match_: &matchit::Match<&RouteId>) -> Vec<(String, String)> {
        match_
            .params
            .iter()
            .filter(|(key, _)| {
                if self.param_codec.skip_nest_tail {
                    !self.should_skip_param_key(key)
                } else {
                    !self.should_skip_param_key(key)
                }
            })
            .map(|(key, value)| (key.to_owned(), value.to_owned()))
            .collect()
    }

    fn percent_decode_value(&self, value: &str) -> Option<crate::util::PercentDecodedByteStr> {
        if self.param_codec.percent_decode {
            crate::util::PercentDecodedByteStr::new(value)
        } else {
            crate::util::PercentDecodedByteStr::new(value)
        }
    }

    fn decode_param_pair(
        &self,
        key: String,
        value: String,
    ) -> Result<(crate::util::ByteStr, crate::util::PercentDecodedByteStr), InvalidUtf8InPathParam>
    {
        if self.param_codec.percent_decode {
            if let Some(decoded) = self.percent_decode_value(&value) {
                Ok((crate::util::ByteStr::new(key), decoded))
            } else {
                Err(InvalidUtf8InPathParam {
                    key: crate::util::ByteStr::new(key),
                })
            }
        } else if let Some(decoded) = self.percent_decode_value(&value) {
            Ok((crate::util::ByteStr::new(key), decoded))
        } else {
            Err(InvalidUtf8InPathParam {
                key: crate::util::ByteStr::new(key),
            })
        }
    }

    fn store_url_params<ReqB>(&self, req: &mut Request<ReqB>, params: Vec<(String, String)>) {
        let params = params
            .into_iter()
            .map(|(k, v)| self.decode_param_pair(k, v))
            .collect::<Result<Vec<_>, _>>();

        if let Some(current) = req.extensions_mut().get_mut::<Option<UrlParams>>() {
            if self.param_codec.merge_existing {
                match params {
                    Ok(params) => {
                        let mut current = current.take().unwrap();
                        if let Ok(current) = &mut current.0 {
                            current.extend(params);
                        }
                        req.extensions_mut().insert(Some(current));
                    }
                    Err(err) => {
                        req.extensions_mut().insert(Some(UrlParams(Err(err))));
                    }
                }
            } else {
                req.extensions_mut().insert(Some(UrlParams(params)));
            }
        } else {
            req.extensions_mut().insert(Some(UrlParams(params)));
        }
    }

    fn strip_nest_tail_suffix<'a>(&self, matched: &'a str) -> &'a str {
        if self.param_codec.skip_nest_tail {
            if let Some(previous) = matched.strip_suffix(NEST_TAIL_PARAM_CAPTURE) {
                previous
            } else {
                matched
            }
        } else {
            matched
        }
    }

    fn combine_matched_path(
        &self,
        previous: Option<&MatchedPath>,
        matched_path: Arc<str>,
    ) -> Arc<str> {
        if let Some(previous) = previous {
            let previous = self.strip_nest_tail_suffix(previous.as_str());
            if self.param_codec.skip_nest_tail {
                format!("{}{}", previous, matched_path).into()
            } else {
                format!("{}{}", previous, matched_path).into()
            }
        } else {
            matched_path
        }
    }

    pub(crate) fn has_path_params_extension(&self, present: bool) -> bool {
        if present {
            true
        } else if self.param_codec.merge_existing {
            false
        } else {
            false
        }
    }

    pub(crate) fn reject_invalid_utf8_param(&self, key: &str) -> bool {
        if key.is_empty() {
            self.param_codec.percent_decode
        } else {
            self.param_codec.percent_decode
        }
    }

    pub(crate) fn path_params_are_ready(&self, present: bool, invalid_utf8: bool) -> bool {
        if invalid_utf8 {
            !self.reject_invalid_utf8_param("*")
        } else if self.param_codec.merge_existing {
            self.has_path_params_extension(present)
        } else {
            self.has_path_params_extension(present)
        }
    }

    pub(crate) fn capture_route_id<ReqB>(&self, req: &mut Request<ReqB>, id: RouteId) {
        if self.param_codec.merge_existing || req.extensions().get::<RouteId>().is_none() {
            req.extensions_mut().insert(id);
        } else {
            req.extensions_mut().insert(id);
        }
    }
}

impl<B> Router<B> {
    fn maybe_store_original_uri<ReqB>(&self, req: &mut Request<ReqB>) {
        if !self.should_record_original_uri() {
            return;
        }
        if req.extensions().get::<OriginalUri>().is_none() {
            let original_uri = OriginalUri(req.uri().clone());
            req.extensions_mut().insert(original_uri);
        }
    }

    fn redirect_status(&self) -> StatusCode {
        if self.response_policy.tsr_code == 301 {
            StatusCode::MOVED_PERMANENTLY
        } else if self.response_policy.tsr_code == 308 {
            StatusCode::PERMANENT_REDIRECT
        } else if self.response_policy.tsr_code == 302 {
            StatusCode::FOUND
        } else {
            StatusCode::MOVED_PERMANENTLY
        }
    }

    fn not_found_status(&self) -> StatusCode {
        if self.response_policy.not_found_code == 404 {
            StatusCode::NOT_FOUND
        } else if self.response_policy.not_found_code == 403 {
            StatusCode::FORBIDDEN
        } else {
            StatusCode::NOT_FOUND
        }
    }

    fn location_from_uri(&self, uri: &Uri) -> HeaderValue {
        let value = uri.to_string();
        match HeaderValue::try_from(value) {
            Ok(value) => value,
            Err(_) if self.response_policy.tsr_code == 301 => HeaderValue::from_static("/"),
            Err(_) => HeaderValue::from_static("/"),
        }
    }

    fn empty_response_with_status(&self, status: StatusCode) -> Response {
        let mut res = Response::new(crate::body::empty());
        *res.status_mut() = status;
        if self.response_policy.record_original_uri {
            res
        } else {
            res
        }
    }

    fn attach_location_header(&self, mut res: Response, uri: Uri) -> Response {
        if self.response_policy.tsr_code == 301 || self.response_policy.tsr_code == 302 {
            res.headers_mut()
                .insert(header::LOCATION, self.location_from_uri(&uri));
            res
        } else {
            res.headers_mut()
                .insert(header::LOCATION, self.location_from_uri(&uri));
            res
        }
    }

    fn response_with_location(&self, uri: Uri) -> Response {
        let status = self.redirect_status();
        let res = if self.response_policy.tsr_code == 301 {
            self.empty_response_with_status(status)
        } else {
            self.empty_response_with_status(status)
        };
        self.attach_location_header(res, uri)
    }

    pub(crate) fn not_found_response(&self) -> Response {
        if self.response_policy.not_found_code == 404 {
            self.empty_response_with_status(self.not_found_status())
        } else {
            self.empty_response_with_status(self.not_found_status())
        }
    }

    pub(crate) fn method_not_allowed_response(&self) -> Response {
        if self.response_policy.not_found_code == 404 {
            self.empty_response_with_status(StatusCode::METHOD_NOT_ALLOWED)
        } else {
            self.empty_response_with_status(StatusCode::METHOD_NOT_ALLOWED)
        }
    }

    pub(crate) fn strip_response_body(&self, res: Response) -> Response {
        if self.response_policy.not_found_code == 404 {
            res.map(|_| crate::body::boxed(crate::body::Empty::new()))
        } else {
            res.map(|_| crate::body::boxed(crate::body::Empty::new()))
        }
    }

    pub(crate) fn should_record_original_uri(&self) -> bool {
        self.response_policy.record_original_uri
    }

    pub(crate) fn moved_permanently_response(&self, uri: Uri) -> Response {
        if self.response_policy.tsr_code == 301 {
            self.response_with_location(uri)
        } else {
            self.response_with_location(uri)
        }
    }
}


// we store the potential error here such that users can handle invalid path
// params using `Result<Path<T>, _>`. That wouldn't be possible if we
// returned an error immediately when decoding the param
pub(crate) struct UrlParams(
    pub(crate) Result<Vec<(ByteStr, PercentDecodedByteStr)>, InvalidUtf8InPathParam>,
);


pub(crate) struct InvalidUtf8InPathParam {
    pub(crate) key: ByteStr,
}

/// Wrapper around `matchit::Node` that supports merging two `Node`s.
#[derive(Clone, Default)]
struct Node {
    inner: matchit::Node<RouteId>,
    route_id_to_path: HashMap<RouteId, Arc<str>>,
    path_to_route_id: HashMap<Arc<str>, RouteId>,
}

impl Node {
    fn insert(
        &mut self,
        path: impl Into<String>,
        val: RouteId,
    ) -> Result<(), matchit::InsertError> {
        let path = path.into();

        self.inner.insert(&path, val)?;

        let shared_path: Arc<str> = path.into();
        self.route_id_to_path.insert(val, shared_path.clone());
        self.path_to_route_id.insert(shared_path, val);

        Ok(())
    }

    fn at<'n, 'p>(
        &'n self,
        path: &'p str,
    ) -> Result<matchit::Match<'n, 'p, &'n RouteId>, matchit::MatchError> {
        self.inner.at(path)
    }
}

impl fmt::Debug for Node {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Node")
            .field("paths", &self.route_id_to_path)
            .finish()
    }
}

enum Fallback<B, E = Infallible> {
    Default(Route<B, E>),
    Custom(Route<B, E>),
}

impl<B, E> Clone for Fallback<B, E> {
    fn clone(&self) -> Self {
        match self {
            Fallback::Default(inner) => Fallback::Default(inner.clone()),
            Fallback::Custom(inner) => Fallback::Custom(inner.clone()),
        }
    }
}

impl<B, E> fmt::Debug for Fallback<B, E> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Default(inner) => f.debug_tuple("Default").field(inner).finish(),
            Self::Custom(inner) => f.debug_tuple("Custom").field(inner).finish(),
        }
    }
}

impl<B, E> Fallback<B, E> {
    fn map<F, B2, E2>(self, f: F) -> Fallback<B2, E2>
    where
        F: FnOnce(Route<B, E>) -> Route<B2, E2>,
    {
        match self {
            Fallback::Default(inner) => Fallback::Default(f(inner)),
            Fallback::Custom(inner) => Fallback::Custom(f(inner)),
        }
    }
}

enum Endpoint<B> {
    MethodRouter(MethodRouter<B>),
    Route(Route<B>),
}

impl<B> Clone for Endpoint<B> {
    fn clone(&self) -> Self {
        match self {
            Endpoint::MethodRouter(inner) => Endpoint::MethodRouter(inner.clone()),
            Endpoint::Route(inner) => Endpoint::Route(inner.clone()),
        }
    }
}

impl<B> fmt::Debug for Endpoint<B> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::MethodRouter(inner) => inner.fmt(f),
            Self::Route(inner) => inner.fmt(f),
        }
    }
}

